<script setup>
import {Head,useForm} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PageBanner from '../../Components/PageBanner.vue'; defineOptions({layout:AppLayout}); const p=defineProps({refill:Object,role:String}); const revision=useForm({line_id:'',quantity:'',reason:''}); const shipment=useForm({document_no:'',expedition:'',shipped_at:new Date().toISOString().slice(0,16),lines:p.refill.lines.map(x=>({refill_line_id:x.id,quantity:x.quantity}))}); const closing=useForm({reason:''}); const review=(r,approve)=>useForm({approve,note:approve?'Disetujui':'Ditolak'}).post(r.review_url);
</script>
<template><Head :title="refill.number"/><div class="units-page"><PageBanner :title="refill.number" :description="`${refill.vendor} · ${refill.status}`" icon="truck"/><section class="surface-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Barang</th><th>Diminta</th><th>Riwayat revisi</th></tr></thead><tbody><tr v-for="l in refill.lines" :key="l.id"><td>{{l.item}}</td><td>{{l.quantity}}</td><td><div v-for="r in l.revisions" :key="r.id">{{r.quantity}} · {{r.status}} · {{r.reason}} <template v-if="role==='admin'&&r.status==='PENDING'"><button class="text-button" @click="review(r,true)">Setujui</button><button class="text-button" @click="review(r,false)">Tolak</button></template></div><span v-if="!l.revisions.length">—</span></td></tr></tbody></table></div></section><section v-if="role==='vendor'" class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="revision.post(refill.revision_url)"><h2>Usulkan revisi</h2><select v-model="revision.line_id" class="form-input" required><option value="">Pilih barang</option><option v-for="l in refill.lines" :key="l.id" :value="l.id">{{l.item}}</option></select><input v-model="revision.quantity" class="form-input" type="number" min="0.0001" step="0.0001" placeholder="Quantity mampu dikirim" required/><textarea v-model="revision.reason" class="form-input" placeholder="Alasan" required/><button class="button button--secondary">Kirim revisi</button></form><form class="form-card__body form-stack" @submit.prevent="shipment.post(refill.shipment_url)"><h2>Tandai dikirim</h2><input v-model="shipment.document_no" class="form-input" placeholder="Nomor DO/surat jalan" required/><input v-model="shipment.expedition" class="form-input" placeholder="Ekspedisi"/><input v-model="shipment.shipped_at" class="form-input" type="datetime-local" required/><div v-for="x in shipment.lines" :key="x.refill_line_id"><label>{{refill.lines.find(l=>l.id===x.refill_line_id)?.item}}</label><input v-model="x.quantity" class="form-input" type="number" min="0.0001" step="0.0001" required/></div><button class="button button--primary">Simpan pengiriman</button></form></section><section v-if="role==='admin'&&!['COMPLETED','CLOSED_PARTIAL'].includes(refill.status)" class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="closing.post(refill.close_url)"><h2>Tutup sisa refill</h2><textarea v-model="closing.reason" class="form-input" placeholder="Alasan wajib" required/><button class="button button--danger">Tutup Sisa</button></form></section></div></template>
